    "beats": {
      "observe": [
        {
          "ja": "季節ごとに水が増える時と減る時を調べます。答えに条件を添えます。",
          "zh": "你查明各季節何時漲水、退水，在答案旁補上條件。"
        },
        {
          "ja": "問題の情報が足りるか考え、今の橋を渡る時間を選ぶ前に判断の根拠を確認します。",
          "zh": "你思考題目資訊是否足夠，在選擇現在的過橋時間前確認判斷依據。"
        }
      ],
      "help": [
        {
          "ja": "白と問題を読み、答えを選ぶ前に、どの季節の条件か尋ねます。",
          "zh": "你和白讀題，選答案前先問是哪個季節的條件。"
        },
        {
          "ja": "水が増える理由と減る理由を一緒に調べます。判断に足りる情報を集めます。",
          "zh": "你們一起查明漲退水原因，蒐集足以判斷的資訊。"
        }
      ]
    },
    "checks": {
      "observe": [
        {
          "id": "N3-3-observe-1",
          "mode": "reading",
          "prompt": "這份說明可以直接用在冬天嗎？",
          "ja": "夏なら朝の水が少ない。冬についてはまだ調べていない。季節によって状況は変わる。",
          "translation": "夏天早晨水少，冬天還沒調查，狀況會因季節改變。",
          "options": [
            "冬の条件を確認する必要がある",
            "冬も必ず朝が安全だ",
            "冬は必ず渡れない"
          ],
          "answer": 0,
          "explanation": "未調查代表不知道，不能推出一定安全或一定不能過。"
        },
        {
          "id": "N3-3-observe-2",
          "mode": "listening",
          "prompt": "回答之前還缺什麼資訊？",
          "ja": "橋の高さは分かりました。水が増える時刻が分かれば、渡る時間を選べます。",
          "translation": "已知道橋高，只要知道漲水時間，就能選擇過橋時段。",
          "options": [
            "橋の名前",
            "水が増える時刻",
            "橋の高さ"
          ],
          "answer": 1,
          "explanation": "「分かれば」指出尚需取得的條件。"
        },
        {
          "id": "N3-3-observe-3",
          "mode": "response",
          "prompt": "別人要你只選早晚，但條件不足，怎麼問？",
          "ja": "「朝と夕方、どちらがいいですか。」季節の情報はありません。",
          "translation": "對方問早上或傍晚哪個好，但沒有季節資訊。",
          "options": [
            "いつでも朝だけが正解です。",
            "質問には必ず答えが一つあります。",
            "どの季節についての質問ですか。"
          ],
          "answer": 2,
          "explanation": "詢問缺少的季節，可讓判斷有根據。"
        }
      ],
      "help": [
        {
          "id": "N3-3-help-1",
          "mode": "reading",
          "prompt": "兩人的答案能否同時有根據？",
          "ja": "アキは夏の記録から朝を選んだ。ユイは秋の記録から夕方を選んだ。水位の変化は季節で異なる。",
          "translation": "秋依夏季紀錄選早上，結依秋季紀錄選傍晚，水位變化因季節不同。",
          "options": [
            "答えが違うので必ず一人がうそをついている",
            "条件が違うので両方に根拠があり得る",
            "条件を見なくても一つに決められる"
          ],
          "answer": 1,
          "explanation": "不同條件可能支持不同結論，仍應核對各自資料。"
        },
        {
          "id": "N3-3-help-2",
          "mode": "listening",
          "prompt": "白打算如何改變做法？",
          "ja": "前は一つの答えを消しました。今度は、条件を聞いてから判断します。",
          "translation": "以前我會刪掉其中一個答案，這次先問條件再判斷。",
          "options": [
            "二つともすぐ消す",
            "先に答えを決める",
            "条件を聞いてから判断する"
          ],
          "answer": 2,
          "explanation": "「前は／今度は」對照舊做法與新做法。"
        },
        {
          "id": "N3-3-help-3",
          "mode": "response",
          "prompt": "對方急著選邊，你如何一起處理？",
          "ja": "「違う答えがあると不安です。どちらかを消したいです。」",
          "translation": "「有不同答案讓我不安，我想刪掉一個。」",
          "options": [
            "不安なのですね。まず条件の違いを一緒に調べませんか。",
            "不安なら両方消しましょう。",
            "違う答えはすべて正しいです。"
          ],
          "answer": 0,
          "explanation": "先接住不安，再查條件；並不因此宣告所有答案都對。"
        }
      ]
    }
