    "beats": {
      "observe": [
        {
          "ja": "過去の管理について質問し、鍵を使った決定の影響と責任を記します。",
          "zh": "你詢問過去的管理，記下使用鑰匙的決定造成什麼影響，以及誰負責。"
        },
        {
          "ja": "被害を認める白と現場へ戻る計画を立てます。謝ることと許すことは別だと確認します。",
          "zh": "你和承認損害的白規劃回到現場，確認道歉與原諒是兩回事。"
        }
      ],
      "help": [
        {
          "ja": "白は過去の責任を認めると、鍵を持って戻ることにしました。",
          "zh": "白承認過去的責任後，決定帶鑰匙回去。"
        },
        {
          "ja": "管理の影響で被害を受けた人に謝る場を用意します。許すかどうかは本人に任せます。",
          "zh": "你安排向受管理措施影響的人道歉，是否原諒則由本人決定。"
        }
      ]
    },
    "checks": {
      "observe": [
        {
          "id": "N3-4-observe-1",
          "mode": "reading",
          "prompt": "道歉之後還要做什麼？",
          "ja": "管理者は謝った。しかし、鍵を返しても、閉じた通路が全部直るわけではない。被害の確認が残っている。",
          "translation": "管理者道歉了，但即使歸還鑰匙，也不代表關閉的通道全修好了，仍要確認損害。",
          "options": [
            "修復をすべて終了とする",
            "被害を確認する",
            "記録を消す"
          ],
          "answer": 1,
          "explanation": "「残っている」明示仍待完成的工作。"
        },
        {
          "id": "N3-4-observe-2",
          "mode": "listening",
          "prompt": "誰承認哪一項責任？",
          "ja": "門を閉めると決めたのは私です。鍵を運んだ人に決定の責任はありません。",
          "translation": "決定關門的是我，搬運鑰匙的人不負這個決定的責任。",
          "options": [
            "運搬者が閉門を決定した",
            "誰も責任を認めていない",
            "話者が閉門の決定を認めた"
          ],
          "answer": 2,
          "explanation": "區分做決定與執行搬運，不任意轉嫁責任。"
        },
        {
          "id": "N3-4-observe-3",
          "mode": "response",
          "prompt": "有人用好意作為免責理由，你如何回應？",
          "ja": "「守りたかったのだから、被害を調べなくてもいいでしょう。」",
          "translation": "「我是想保護大家，所以不用調查損害了吧？」",
          "options": [
            "理由は聞きますが、影響も確かめる必要があります。",
            "よい理由なら被害はありません。",
            "理由を聞いたので全員が許しました。"
          ],
          "answer": 0,
          "explanation": "承認可聽原因，仍保留查明影響的必要。"
        }
      ],
      "help": [
        {
          "id": "N3-4-help-1",
          "mode": "reading",
          "prompt": "被影響者目前的立場是什麼？",
          "ja": "説明は聞きます。でも、今すぐ許すとは約束できません。まず道を直してください。",
          "translation": "我會聽說明，但不能答應立刻原諒，請先修路。",
          "options": [
            "もう全面的に許した",
            "修理も説明も拒んでいる",
            "説明は聞くが、すぐ許すとは限らない"
          ],
          "answer": 2,
          "explanation": "閱讀各項意願，不把願意聽解釋等同原諒。"
        },
        {
          "id": "N3-4-help-2",
          "mode": "listening",
          "prompt": "今天能做的修復是什麼？",
          "ja": "今日は東の門だけ開けられます。西の門は明日、道具を持って戻ります。",
          "translation": "今天只能開東門，西門明天帶工具回來處理。",
          "options": [
            "東の門を開ける",
            "東西すべて開ける",
            "西の門だけ開ける"
          ],
          "answer": 0,
          "explanation": "「だけ」限制今天的範圍，西門另有時間安排。"
        },
        {
          "id": "N3-4-help-3",
          "mode": "response",
          "prompt": "有人暫時不願見白，你如何尊重？",
          "ja": "「今は会いたくありません。でも、通路の修理はお願いします。」",
          "translation": "「我現在不想見他，但請把通道修好。」",
          "options": [
            "修理するので、必ず会ってください。",
            "会うことは無理に求めず、修理を進めます。",
            "会わないなら修理もしません。"
          ],
          "answer": 1,
          "explanation": "見面意願與修復責任可分別處理，不能交換強迫原諒。"
        }
      ]
    }
